"""Generates ``docs/RESULTS.md`` from every ``metrics.json`` under ``artifacts/`` — the file is
regenerated wholesale each time, never hand-edited, so every number in it is traceable to the
run that produced it.
"""

import json
from pathlib import Path

_HEADER = (
    "<!-- AUTO-GENERATED by `pdm evaluate` (pdm.evaluation.results). Do not hand-edit; "
    "re-run `pdm evaluate` instead. -->"
)


def _load_all_metrics(artifacts_dir: Path) -> list[dict]:
    return [
        json.loads(p.read_text(encoding="utf-8"))
        for p in sorted(artifacts_dir.glob("*/metrics.json"))
    ]


def _fmt(entry: dict) -> str:
    return f"{entry['mean']:.3f} ± {entry['std']:.3f}"


def _mlflow_runs_cell(payload: dict) -> str:
    """One cell listing every seed's MLflow run id, truncated to 8 characters (matching
    ``pdm registry compare``'s display convention) — the constraint that "every number in
    docs/RESULTS.md must be traceable to an MLflow run id." Falls back to an em dash for a
    ``metrics.json`` written before this milestone added the field, rather than crashing on a
    missing key.
    """
    run_ids = payload.get("mlflow_run_ids")
    if not run_ids:
        return "—"
    return ", ".join(f"`{run_id[:8]}`" for run_id in run_ids.values())


def _rul_table(payloads: list[dict]) -> str:
    rows = [p for p in payloads if p["task"] == "rul_regression"]
    if not rows:
        return ""
    lines = [
        "### RUL regression (C-MAPSS)",
        "",
        "| Model | Subset | Val RMSE | Val MAE | Test RMSE | Test MAE | Test NASA score "
        "| Run | MLflow Runs |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for r in sorted(rows, key=lambda r: r["test"]["rmse"]["mean"]):
        lines.append(
            f"| {r['model']} | {r['subset']} | {_fmt(r['val']['rmse'])} | {_fmt(r['val']['mae'])} "
            f"| {_fmt(r['test']['rmse'])} | {_fmt(r['test']['mae'])} "
            f"| {_fmt(r['test']['nasa_score'])} | `{r['run_id']}` | {_mlflow_runs_cell(r)} |"
        )
    return "\n".join(lines)


def _failure_table(payloads: list[dict]) -> str:
    rows = [p for p in payloads if p["task"] == "failure_classification"]
    if not rows:
        return ""
    lines = [
        "### Failure-within-W classification (C-MAPSS)",
        "",
        "| Model | Subset | Val PR-AUC | Val ROC-AUC | Test PR-AUC | Test ROC-AUC "
        "| Test F1 | Run | MLflow Runs |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for r in sorted(rows, key=lambda r: -r["test"]["pr_auc"]["mean"]):
        lines.append(
            f"| {r['model']} | {r['subset']} | {_fmt(r['val']['pr_auc'])} "
            f"| {_fmt(r['val']['roc_auc'])} | {_fmt(r['test']['pr_auc'])} "
            f"| {_fmt(r['test']['roc_auc'])} | {_fmt(r['test']['f1'])} | `{r['run_id']}` "
            f"| {_mlflow_runs_cell(r)} |"
        )
    return "\n".join(lines)


def _ai4i_table(payloads: list[dict]) -> str:
    rows = [p for p in payloads if p["task"] == "ai4i_failure_classification"]
    if not rows:
        return ""
    lines = [
        "### AI4I failure classification (tabular baseline, no held-out test file)",
        "",
        "| Model | Val PR-AUC | Val ROC-AUC | Val F1 | Val Precision | Val Recall | Run "
        "| MLflow Runs |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for r in sorted(rows, key=lambda r: -r["val"]["pr_auc"]["mean"]):
        lines.append(
            f"| {r['model']} | {_fmt(r['val']['pr_auc'])} | {_fmt(r['val']['roc_auc'])} "
            f"| {_fmt(r['val']['f1'])} | {_fmt(r['val']['precision'])} "
            f"| {_fmt(r['val']['recall'])} | `{r['run_id']}` | {_mlflow_runs_cell(r)} |"
        )
    return "\n".join(lines)


ANOMALY_SUMMARY_PATH = Path("artifacts/anomaly_experiments/summary.json")


def _anomaly_detector_row(name: str, m: dict, runs_cell: str) -> str:
    return (
        f"| {name} | {_fmt(m['f1'])} | {_fmt(m['precision'])} "
        f"| {_fmt(m['recall'])} | {_fmt(m['pr_auc'])} | {runs_cell} |"
    )


def _anomaly_table(summary_path: Path) -> str:
    """P06's own required RESULTS.md entry (spec: "Put both in docs/RESULTS.md") — sourced from
    ``artifacts/anomaly_experiments/summary.json`` rather than the per-run ``metrics.json`` glob
    the baseline tables use, since this milestone's sweeps write one shared summary file, not one
    file per detector. Skips entirely (like every other section here) if that file doesn't exist
    yet — a fresh clone before `pdm anomaly` has run.

    Every row within a dataset block (C-MAPSS or NAB) shares the same "MLflow Runs" cell — all of
    AE-alone/Isolation-Forest-alone/every fused threshold style are measured from the *same*
    per-seed run (one ``start_run`` per seed logs all of them together;
    ``pdm.models.torch.anomaly_experiments.final_cmapss_evaluation``/``final_nab_evaluation``),
    so that's the genuinely correct run-id set for each row, not a placeholder repeated for
    formatting's sake. Satisfies the P07 spec constraint ("every number in docs/RESULTS.md must
    be traceable to an MLflow run id") that this table used to be the one hole in.
    """
    if not summary_path.exists():
        return ""
    payload = json.loads(summary_path.read_text(encoding="utf-8"))
    n_seeds = len(payload["cmapss"]["ae_alone"]["f1"]["seeds"])
    header = [
        "| Detector | F1 | Precision | Recall | PR-AUC | MLflow Runs |",
        "|---|---|---|---|---|---|",
    ]

    cmapss = payload["cmapss"]
    cmapss_runs = _mlflow_runs_cell(cmapss)
    cmapss_rows = [
        _anomaly_detector_row(
            "LSTM autoencoder (percentile-99 threshold)", cmapss["ae_alone"], cmapss_runs
        ),
        _anomaly_detector_row(
            "Isolation Forest (percentile-99 threshold)",
            cmapss["isolation_forest_alone"],
            cmapss_runs,
        ),
        _anomaly_detector_row(
            "Fused, max-F1 threshold", cmapss["fused_by_threshold_style"]["max_f1"], cmapss_runs
        ),
        _anomaly_detector_row(
            "Fused, 90%-precision threshold",
            cmapss["fused_by_threshold_style"]["precision_target"],
            cmapss_runs,
        ),
        _anomaly_detector_row(
            "Fused, percentile-99 threshold",
            cmapss["fused_by_threshold_style"]["percentile_99"],
            cmapss_runs,
        ),
    ]

    nab = payload["nab"]
    nab_runs = _mlflow_runs_cell(nab)
    nab_rows = [
        _anomaly_detector_row(
            "LSTM autoencoder (percentile-99 threshold)", nab["ae_alone"], nab_runs
        ),
        _anomaly_detector_row(
            "Isolation Forest (percentile-99 threshold)", nab["isolation_forest_alone"], nab_runs
        ),
        _anomaly_detector_row("Fused, percentile-99 threshold", nab["fused"], nab_runs),
    ]

    return "\n".join(
        [
            "## Anomaly detection",
            "",
            f"Bottleneck (latent) dimension: `{payload['chosen_latent_dim']}`. Fusion weight "
            f"(LSTM-AE share): `{payload['chosen_fusion_weight']}`, chosen on validation. "
            f"Mean ± std over {n_seeds} seeds.",
            "",
            "### C-MAPSS (healthy vs. late-life windows, test split)",
            "",
            *header,
            *cmapss_rows,
            "",
            "### NAB `machine_temperature_system_failure` (point-wise, test split)",
            "",
            "No labelled validation split exists for a single real time series without either "
            "starving training or leaking the only anomaly labels test would be scored against "
            "— every NAB detector ships the label-free percentile-99-of-healthy-training-scores "
            "threshold (see `pdm/preprocessing/nab_pipeline.py`), not a validation-tuned one.",
            "",
            *header,
            *nab_rows,
        ]
    )


def generate_results_md(
    artifacts_dir: Path, output_path: Path, anomaly_summary_path: Path | None = None
) -> str:
    payloads = _load_all_metrics(artifacts_dir)
    anomaly_summary_path = (
        ANOMALY_SUMMARY_PATH if anomaly_summary_path is None else anomaly_summary_path
    )
    sections = [
        "# Results",
        "",
        _HEADER,
        "",
        "Every number below is mean ± std over the seeds recorded in each run's "
        "`metrics.json` (`artifacts/baselines/<run_id>/metrics.json`, `artifacts/**/metrics.json` "
        "for later milestones). Nothing here is hand-typed.",
        "",
        "## Baselines",
        "",
        _rul_table(payloads),
        "",
        _failure_table(payloads),
        "",
        _ai4i_table(payloads),
        "",
        _anomaly_table(anomaly_summary_path),
        "",
    ]
    content = "\n".join(sections)
    # collapse runs of blank lines left by an empty section
    while "\n\n\n" in content:
        content = content.replace("\n\n\n", "\n\n")
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(content, encoding="utf-8")
    return content
